import xml.etree.ElementTree as ET
import json
import os

def load_config():
    try:
        with open('cache.bin', 'rb') as f:
            return json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        return {}

def parse_xml():
    try:
        tree = ET.parse('config.xml')
        root = tree.getroot()
        items = root.find('items')
        if items is None:
            return {}
        mapping = {}
        for item in items.findall('item'):
            name = item.get('name')
            if name is not None:
                mapping[name] = item.text.strip() if item.text else ''
        return mapping
    except ET.ParseError:
        return {}

def main():
    config = load_config()
    if not config:
        config = parse_xml()
        with open('cache.bin', 'wb') as f:
            json.dump(config, f)
    print(json.dumps({k: v for k, v in sorted(config.items())}, indent=2))

main()

import json
import os
import xml.etree.ElementTree as ET

def load_mapping():
    cache_path = "cache.bin"
    if os.path.exists(cache_path):
        with open(cache_path, "rb") as f:
            return json.load(f)

    config_path = "config.xml"
    if not os.path.exists(config_path):
        raise FileNotFoundError(f"Config file {config_path} not found")

    tree = ET.parse(config_path)
    root = tree.getroot()

    mapping = {}
    items = root.find("items")
    if items is not None:
        for item in items.findall("item"):
            name = item.get("name")
            if name is not None:
                mapping[name] = item.text.strip()

    with open(cache_path, "w") as f:
        json.dump(mapping, f)

    return mapping

def main():
    mapping = load_mapping()
    sorted_mapping = dict(sorted(mapping.items()))
    print(json.dumps(sorted_mapping, indent=2))

if __name__ == "__main__":
    main()

import os
import json
import xml.etree.ElementTree as ET

CACHE_FILE = 'cache.bin'
CONFIG_FILE = 'config.xml'

def load_mapping_from_cache():
    with open(CACHE_FILE, 'r') as f:
        return json.load(f)

def save_mapping_to_cache(mapping):
    with open(CACHE_FILE, 'w') as f:
        json.dump(mapping, f)

def load_mapping_from_xml():
    tree = ET.parse(CONFIG_FILE)
    root = tree.getroot()
    mapping = {}
    for item in root.find('items').findall('item'):
        name = item.get('name')
        text = item.text
        mapping[name] = text
    return mapping

def main():
    if os.path.exists(CACHE_FILE):
        mapping = load_mapping_from_cache()
    else:
        mapping = load_mapping_from_xml()
        save_mapping_to_cache(mapping)
    sorted_mapping = dict(sorted(mapping.items()))
    print(json.dumps(sorted_mapping))

if __name__ == '__main__':
    main()
